from wordfreq import top_words


def test_top_words_basic():
    assert top_words("the cat sat", 10) == [("cat", 1), ("sat", 1), ("the", 1)]


def test_top_words_counts():
    assert top_words("one one two two two", 10) == [("two", 3), ("one", 2)]


def test_top_words_limit():
    assert top_words("a b c", 2) == [("a", 1), ("b", 1)]


def test_top_words_empty():
    assert top_words("", 5) == []


def test_top_words_words_lowercased():
    assert top_words("Hello HELLO world", 10) == [("hello", 2), ("world", 1)]


def test_top_words_apostrophes():
    assert top_words("don't don't don't", 10) == [("don't", 3)]


def test_top_words_ties_alphabetical():
    assert top_words("zebra apple mango", 10) == [
        ("apple", 1),
        ("mango", 1),
        ("zebra", 1),
    ]


def test_top_words_digits_ignored():
    assert top_words("abc 123 xyz 99", 10) == [("abc", 1), ("xyz", 1)]


def test_top_words_zero_limit():
    assert top_words("a b c", 0) == []

